 Begin CmpMap 	# Compound Mapping
    Nin = 2 	# Number of input coordinates
 IsA Mapping 	# Mapping between coordinate systems
    Series = 0 	# Component Mappings applied in parallel
    MapA = 	# First component Mapping
       Begin GrismMap 	# Map 1-d coordinates using a spectral disperser
          Nin = 1 	# Number of input coordinates
       IsA Mapping 	# Mapping between coordinate systems
#         GrmNR = 1 	# Refractive index at the ref. wavelength
          GrmNRP = -50000 	# Rate of change of refractive index
          GrmWR = 4.9999999999999998e-07 	# Ref. wavelength
          GrmAlp = 0.10000000000000001 	# Angle of incidence of incoming light
#         GrmG = 0 	# Grating ruling density
#         GrmM = 0 	# The interference order
#         GrmEps = 0 	# Angle between grating normal and dispersion plane
#         GrmTh = 0 	# Angle between detector normal and reference ray
       End GrismMap
    MapB = 	# Second component Mapping
       Begin ZoomMap 	# Zoom about the origin
          Nin = 1 	# Number of input coordinates
       IsA Mapping 	# Mapping between coordinate systems
          Zoom = 2 	# Zoom factor
       End ZoomMap
 End CmpMap
